def main():
    """Initialize MeTTa runner and demonstrate working queries."""
    print("🧠 Loading MeTTa knowledge base with domain-specific Atomspaces...")
    runner = MeTTa()
    
    try:
        runner.run(METTA_CODE)
        print("   ✅ Knowledge base loaded successfully.")
    except Exception as e:
        print(f"   ❌ Error loading knowledge base: {e}")
        return
    
    # --- Run comprehensive smoke-test queries --- 
    # Query: Find all Military Operations (querying the History space)
    print(f"\n🔍 Find all Military Operations (querying the History space)")
    query = """!(match &history-space (: $op military-operation) $op)"""
    try:
        results = runner.run(query)
        if results and results[0]:
            print("   Results:")
            flat_results = []
            for res in results:
                if isinstance(res, list): flat_results.extend(res)
                else: flat_results.append(res)
            for result in sorted(list(set(map(str, flat_results)))):
                print(f"   - {result}")
        else:
            print("   - No results found.")
    except Exception as e:
        print(f"   - Query error: {e}")

    # Query: What is Béchamel made with? (querying the Culinary Arts space)
    print(f"\n🔍 What is Béchamel made with? (querying the Culinary Arts space)")
    query = """!(match &culinary-arts-space (made-with béchamel $ingredient) $ingredient)"""
    try:
        results = runner.run(query)
        if results and results[0]:
            print("   Results:")
            flat_results = []
            for res in results:
                if isinstance(res, list): flat_results.extend(res)
                else: flat_results.append(res)
            for result in sorted(list(set(map(str, flat_results)))):
                print(f"   - {result}")
        else:
            print("   - No results found.")
    except Exception as e:
        print(f"   - Query error: {e}")

    # Query: Find assertion text for Normandy Landings (querying the History space)
    print(f"\n🔍 Find assertion text for Normandy Landings (querying the History space)")
    query = """!(match &history-space (And (has-assertion normandy-landings $a) (has-text $a $text)) $text)"""
    try:
        results = runner.run(query)
        if results and results[0]:
            print("   Results:")
            flat_results = []
            for res in results:
                if isinstance(res, list): flat_results.extend(res)
                else: flat_results.append(res)
            for result in sorted(list(set(map(str, flat_results)))):
                print(f"   - {result}")
        else:
            print("   - No results found.")
    except Exception as e:
        print(f"   - Query error: {e}")

if __name__ == '__main__':
    main()
